INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf1c', 1, 'Add chicken to a large Dutch oven or stock pot');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf1c', 2, 'Cover with water');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf1c', 3, 'Bring to a boil and simmer for 2 to 2 1/2 hours, skimming any impurities off the top to insure a clear broth');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf1c', 4, 'If your pot is big enough, add the vegetables and spices for the last hour of the cooking time');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf1c', 5, 'My Dutch oven wasn’t big enough to hold everything, just the chicken and other bones filled the pot, so I cooked the meat/bones for the full cooking time, then removed them, and cooked the vegetables and spices separately');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf1c', 6, 'Strain everything out of the broth');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf1c', 7, 'Bone the chicken, pulling the meat into large chunks');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf1c', 8, 'Slice the carrots');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf1c', 9, 'Return the chicken and carrots to the broth');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf1c', 10, 'Cook noodles according to package instructions if you’re using them');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf1c', 11, 'Add noodles to bowl and then top with hot soup');
INSERT INTO recipes (id, name, description, meal_type, servings) VALUES ('00000000-0000-4000-8000-00000000cf24', 'Shawarma', 'Danie: Egyptian. Źródło: TheMealDB', 'lunch', 4) ON CONFLICT (id) DO NOTHING;
