INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000d027', 'Parsley', 0.5, 'szt', 4);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000d027', 'Turmeric', 3, 'ml', 5);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000d027', 'Ground Cumin', 3, 'ml', 6);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000d027', 'Paprika', 3, 'ml', 7);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000d027', 'Ground Ginger', 1, 'ml', 8);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000d027', 'Cayenne Pepper', 1, 'ml', 9);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000d027', 'Salt', 1, 'szt', 10);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000d027', 'Black Pepper', 1, 'szt', 11);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000d027', 'Chicken Thighs', 4, 'szt', 12);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000d027', 'Olive Oil', 1, 'szt', 13);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000d027', 'Raisins', 60, 'ml', 14);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000d027', 'Chicken Stock', 240, 'ml', 15);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000d027', 'Sweet Potatoes', 1, 'szt', 16);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000d027', 'Carrots', 3, 'szt', 17);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000d027', 'Prunes', 60, 'ml', 18);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d027', 1, 'Combine onions, celery, cilantro, and parsley in a large pot. Stir in turmeric, cumin, paprika, ginger, cayenne pepper, salt, and pepper. Place chicken thighs on top. Drizzle olive oil over chicken. Cover and simmer over low heat until chicken is tender, about 40 minutes.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d027', 2, 'Place raisins in a small bowl and cover with hot water; let soak for 10 minutes. Drain.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d027', 3, 'Preheat oven to 400 degrees F (200 degrees C).');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d027', 4, 'Transfer chicken mixture into an oven-safe tagine or casserole dish. Add sweet potato and carrots. Cover with lid or aluminum foil.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d027', 5, 'Bake in the preheated oven until sweet potato is soft, about 40 minutes. Add drained raisins and prunes. Continue baking, covered, until raisins and prunes are heated through, about 10 minutes.');
INSERT INTO recipes (id, name, description, meal_type, servings) VALUES ('00000000-0000-4000-8000-00000000ce46', 'Tandoori chicken', 'Danie: Indian. Źródło: TheMealDB', 'lunch', 4) ON CONFLICT (id) DO NOTHING;
